package io.aetherdb.embedded.typed;import static org.junit.jupiter.api.Assertions.*;import io.aetherdb.api.typed.*;import io.aetherdb.codec.*;import java.util.*;import org.junit.jupiter.api.Test;
class EmbeddedTypedDatabaseTest{@Test void typedPointsBatchAndSnapshotPreserveSemantics(){var definition=CollectionDefinition.of(CollectionId.of("11111111-1111-1111-1111-111111111111"),"users",BuiltInKeyCodecs.signedLong(),BuiltInValueCodecs.utf8String(UUID.fromString("22222222-2222-2222-2222-222222222222")));try(var db=AetherEmbedded.openInMemory()){var users=db.collection(definition);assertTrue(users.get(1L)instanceof ReadResult.NotFound<?>);assertTrue(users.put(1L,"one")instanceof TypedWriteResult.Applied);try(var snapshot=db.snapshot()){var old=snapshot.collection(definition);users.put(1L,"new");assertEquals("one",old.get(1L).requireValue());}var batch=db.batch().put(users,2L,"two").delete(users,1L);var result=db.write(batch);assertEquals(2,((TypedWriteResult.Applied)result).operationCount());assertEquals("two",users.get(2L).requireValue());assertTrue(users.get(1L)instanceof ReadResult.NotFound<?>);}}}
